mapper.select:
select pk.*, p.name as product_name, p.product_no, p.cover_image
from product_knowledge pk
left join product p on pk.product_id = p.id

     and pk.product_id = #{productId}
     and pk.knowledge_type = #{knowledgeType}
     and pk.source_type = #{sourceType}
     and pk.is_enabled = #{isEnabled}
     and pk.title like concat('%', #{title}, '%')
     and pk.content like concat('%', #{content}, '%')
     and p.name like concat('%', #{productName}, '%')

order by pk.sort asc, pk.id desc

mapper.update:
update product_knowledge
product_id = #{productId}, knowledge_type = #{knowledgeType}, title = #{title}, content = #{content}, source_type = #{sourceType}, is_enabled = #{isEnabled}, sort = #{sort}, update_time = #{updateTime},
where id = #{id}
